<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Admin;use App\Security;
Admin::requirePermission('products.view');$pdo=db();$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='save'){Admin::requirePermission('products.manage');$name=trim((string)($_POST['name']??''));$sku=strtoupper(trim((string)($_POST['sku']??'')));$cat=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock_quantity']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'draft');$compliance=(string)($_POST['compliance_status']??'pending');if(mb_strlen($name)<2||mb_strlen($name)>220||!preg_match('/^[A-Z0-9_-]{2,100}$/',$sku)||!$price||$price<=0||$price>999999999||$stock===false||$stock<0||!in_array($status,['draft','active','hidden','archived'],true)||!in_array($compliance,['pending','approved','rejected'],true))throw new RuntimeException('تحقق من الاسم والرمز والسعر والكمية والحالة.');$q=$pdo->prepare("SELECT id FROM categories WHERE id=?");$q->execute([$cat]);if(!$q->fetchColumn())throw new RuntimeException('اختر قسماً صحيحاً.');
  $slug=Admin::slug((string)($_POST['slug']??$name));$short=trim((string)($_POST['short_description']??''));$desc=trim((string)($_POST['description']??''));$low=max(0,(int)($_POST['low_stock_threshold']??5));$featured=isset($_POST['is_featured'])?1:0;
  $pdo->beginTransaction();
  if($id){$q=$pdo->prepare("SELECT stock_quantity,reserved_quantity FROM products WHERE id=? FOR UPDATE");$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('المنتج غير موجود.');if($stock<(int)$old['reserved_quantity'])throw new RuntimeException('لا يمكن جعل المخزون أقل من الكمية المحجوزة للطلبات.');$delta=$stock-(int)$old['stock_quantity'];$q=$pdo->prepare("UPDATE products SET category_id=?,name=?,slug=?,sku=?,short_description=?,description=?,price=?,stock_quantity=?,low_stock_threshold=?,status=?,compliance_status=?,is_featured=? WHERE id=?");$q->execute([$cat,$name,$slug,$sku,$short?:null,$desc?:null,$price,$stock,$low,$status,$compliance,$featured,$id]);if($delta!==0)$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity,note) VALUES(?,?,'adjustment',?,'تعديل كمية من شاشة المنتج')")->execute([$id,($_SESSION['admin_user']['id']??null),$delta]);}
  else{$q=$pdo->prepare("INSERT INTO products(category_id,name,slug,sku,short_description,description,price,stock_quantity,low_stock_threshold,status,compliance_status,is_featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$cat,$name,$slug,$sku,$short?:null,$desc?:null,$price,$stock,$low,$status,$compliance,$featured]);$id=(int)$pdo->lastInsertId();if($stock>0)$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity,note) VALUES(?,?,'in',?,'رصيد افتتاحي')")->execute([$id,($_SESSION['admin_user']['id']??null),$stock]);}
  if(isset($_FILES['images'])&&is_array($_FILES['images']['name']??null)){ $hasPrimary=(int)$pdo->query("SELECT COUNT(*) FROM product_images WHERE product_id=".(int)$id." AND is_primary=1")->fetchColumn()>0; $count=count($_FILES['images']['name']); for($i=0;$i<$count;$i++){if(($_FILES['images']['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$file=['name'=>$_FILES['images']['name'][$i],'type'=>$_FILES['images']['type'][$i],'tmp_name'=>$_FILES['images']['tmp_name'][$i],'error'=>$_FILES['images']['error'][$i],'size'=>$_FILES['images']['size'][$i]];$path=Admin::uploadImage($file);$primary=$hasPrimary?0:1;$pdo->prepare("INSERT INTO product_images(product_id,image_path,alt_text,is_primary,sort_order) VALUES(?,?,?,?,?)")->execute([$id,$path,$name,$primary,$i]);$hasPrimary=true;}}
  $pdo->commit();Admin::audit('product.save','product',$id);header('Location: products.php?saved=1');exit;
 }
 if($action==='delete'){Admin::requirePermission('products.manage');$pdo->prepare("DELETE FROM products WHERE id=?")->execute([$id]);Admin::audit('product.delete','product',$id);header('Location: products.php?deleted=1');exit;}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر الحفظ. تحقق من عدم تكرار SKU أو رابط المنتج.';}}
if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM products WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$categories=$pdo->query("SELECT id,name FROM categories ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 250")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إدارة المنتجات | الفخامة</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1200px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:20px;margin:18px 0}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.fields label{display:block;color:#d9c49c}.fields input,.fields textarea,.fields select{width:100%;padding:10px;background:#080808;color:#fff;border:1px solid #49371c;border-radius:8px;font:inherit}.fields textarea{min-height:75px}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:10px;border-bottom:1px solid #342718}.table-wrap{overflow:auto}.actions{display:flex;gap:6px;align-items:center}.actions form{margin:0}@media(max-width:750px){.fields{grid-template-columns:1fr 1fr}.table{min-width:760px}}@media(max-width:450px){.fields{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إدارة المنتجات</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice">تم حفظ المنتج.</div><?php endif;?><section class="panel"><h2><?=$edit?'تعديل المنتج':'إضافة منتج'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="fields"><label>اسم المنتج<input name="name" required maxlength="220" value="<?=e($edit['name']??'')?>"></label><label>رمز SKU<input name="sku" required value="<?=e($edit['sku']??'')?>"></label><label>القسم<select name="category_id" required><option value="">اختر القسم</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id']?'selected':'')?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>السعر (ريال)<input type="number" name="price" min=".01" step=".01" required value="<?=e((string)($edit['price']??''))?>"></label><label>الكمية المتاحة<input type="number" name="stock_quantity" min="0" required value="<?=e((string)($edit['stock_quantity']??0))?>"></label><label>حد التنبيه للمخزون<input type="number" name="low_stock_threshold" min="0" value="<?=e((string)($edit['low_stock_threshold']??5))?>"></label><label>الرابط<input name="slug" value="<?=e($edit['slug']??'')?>"></label><label>حالة العرض<select name="status"><?php foreach(['draft'=>'مسودة','active'=>'نشط','hidden'=>'مخفي','archived'=>'مؤرشف'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['status']??'draft')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>حالة الامتثال<select name="compliance_status"><?php foreach(['pending'=>'بانتظار التحقق','approved'=>'معتمد','rejected'=>'مرفوض'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['compliance_status']??'pending')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>وصف مختصر<input name="short_description" maxlength="500" value="<?=e($edit['short_description']??'')?>"></label><label>صور المنتج (يمكن اختيار عدة صور، كل صورة حتى 5MB)<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple></label><label>الوصف الكامل<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label><input type="checkbox" name="is_featured" style="width:auto" <?=!empty($edit['is_featured'])?'checked':''?>> منتج مميز</label></div><p><button class="btn btn-gold">حفظ المنتج</button> <a class="btn btn-outline" href="products.php">إضافة جديد</a></p><small style="color:#aaa">اعتماد الامتثال مسؤولية المدير بعد التحقق النظامي. لا تعتمد منتجاً لمجرد إدخاله.</small></form></section><section class="panel"><h2>قائمة المنتجات</h2><div class="table-wrap"><table class="table"><thead><tr><th>المنتج</th><th>SKU</th><th>القسم</th><th>السعر</th><th>المخزون</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['sku'])?></td><td><?=e($r['category_name']??'—')?></td><td><?=number_format((float)$r['price'],2)?> ر.س</td><td><?=(int)$r['stock_quantity']?> / محجوز <?=(int)$r['reserved_quantity']?></td><td><?=e($r['status'])?> · <?=e($r['compliance_status'])?></td><td class="actions"><a class="btn btn-outline" href="?edit=<?=(int)$r['id']?>">تعديل</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-outline">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>